def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Find the row containing the longest contiguous non-background run.
    best = (0, 0, 0)
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start > best[0]:
                best = (c - start, r, start)

    length, motif_row, motif_start = best
    motif = grid[motif_row][motif_start:motif_start + length]

    # The scattered marker color is the most frequent non-background
    # color outside the motif.
    outside = Counter()
    for r in range(h):
        for c in range(w):
            if r == motif_row and motif_start <= c < motif_start + length:
                continue
            if grid[r][c] != bg:
                outside[grid[r][c]] += 1
    marker = outside.most_common(1)[0][0]

    out = [row[:] for row in grid]
    anchor = length // 2
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker]
    for r, c in markers:
        start = c - anchor
        for i, value in enumerate(motif):
            x = start + i
            if 0 <= x < w:
                out[r][x] = value

    return out
